use std::future::{Future, poll_fn};
use std::pin::{Pin, pin};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};
use std::time::{Duration, Instant};

async fn task(name: &str, ms: u64) -> u64 {
    println!("{name} starts");
    sleep(Duration::from_millis(ms)).await;
    println!("{name} done after {ms} ms");
    ms
}

fn main() {
    let start = Instant::now();
    let (a, b) = block_on(join2(task("slow", 300), task("fast", 100)));
    let elapsed = start.elapsed().as_millis();
    println!("results {a} and {b}; took about 300 ms, not 400: {}", elapsed < 390);
}

// ---- a tiny runtime: block_on, sleep and join2 ----

struct ThreadWaker(Thread);
impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) {
        self.0.unpark();
    }
}

fn block_on<F: Future>(fut: F) -> F::Output {
    let mut fut = pin!(fut);
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(v) => return v,
            Poll::Pending => thread::park(),
        }
    }
}

struct Sleep {
    state: Arc<Mutex<(bool, Option<Waker>)>>, // (done, waker to call)
}

fn sleep(d: Duration) -> Sleep {
    let state = Arc::new(Mutex::new((false, None::<Waker>)));
    let timer = Arc::clone(&state);
    thread::spawn(move || {
        thread::sleep(d);
        let mut s = timer.lock().unwrap();
        s.0 = true;
        if let Some(w) = s.1.take() {
            w.wake();
        }
    });
    Sleep { state }
}

impl Future for Sleep {
    type Output = ();
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let mut s = self.state.lock().unwrap();
        if s.0 {
            Poll::Ready(())
        } else {
            s.1 = Some(cx.waker().clone());
            Poll::Pending
        }
    }
}

fn join2<A: Future, B: Future>(a: A, b: B) -> impl Future<Output = (A::Output, B::Output)> {
    let (mut a, mut b) = (Box::pin(a), Box::pin(b));
    let (mut ra, mut rb) = (None, None);
    poll_fn(move |cx| {
        if ra.is_none() {
            if let Poll::Ready(v) = a.as_mut().poll(cx) {
                ra = Some(v);
            }
        }
        if rb.is_none() {
            if let Poll::Ready(v) = b.as_mut().poll(cx) {
                rb = Some(v);
            }
        }
        if ra.is_some() && rb.is_some() {
            Poll::Ready((ra.take().unwrap(), rb.take().unwrap()))
        } else {
            Poll::Pending
        }
    })
}

blocks.md:
**Race** (`select`) waits for whichever future finishes first and drops the other. Dropping a future **cancels** it: it is simply never polled again, and its destructors run. That is how a **timeout** works, and *The Rust Programming Language* builds one from `race` and `sleep`:

```rust
async fn timeout<F: Future>(future_to_try: F, max_time: Duration) -> Result<F::Output, Duration> {
    match trpl::race(future_to_try, trpl::sleep(max_time)).await {
        Either::Left(output) => Ok(output),
        Either::Right(_) => Err(max_time),
    }
}
```

Because any future can be dropped at any `.await`, code between awaits should leave data consistent: a future is **cancelled** at an await point, never in the middle of a line.

`spawn` (in Tokio, `tokio::spawn`) hands a future to the runtime as an independent **task**. A multi-threaded runtime may run tasks in parallel on its worker threads, so a spawned future must be `Send + 'static`, usually an `async move` block. Tasks communicate with **async channels**: `tx.send(v)` and `rx.recv().await`, which returns `None` once all senders are gone:

```rust
let (tx, mut rx) = trpl::channel();

let tx_fut = async move {
    for val in ["hi", "from", "the", "future"] {
        tx.send(val.to_string()).unwrap();
        trpl::sleep(Duration::from_millis(500)).await;
    }
};
let rx_fut = async {
    while let Some(value) = rx.recv().await {
        println!("received '{value}'");
    }
};
trpl::join(tx_fut, rx_fut).await;
```

Note the `async move` on the sender: it moves `tx` into the future, so `tx` is dropped when that future finishes, which ends the receiver's `while let` loop. Without `move`, the program would wait forever, the same bug as with thread channels.

